const assert=require('node:assert/strict'),Q=require('./aquatic'),E=require('./ecology');let tests=[],results={};function test(n,f){f();tests.push(n)}function run(s,n){let max=0;for(let i=0;i<n;i++){Q.tick(s);for(let v of Object.values(s.last)){assert.ok(Number.isFinite(v)&&Math.abs(v)<1e-6,JSON.stringify(s.last));max=Math.max(max,Math.abs(v))}for(const c of s.cells)for(const k of ['soilP','rockP','microP','sorbedP'])assert.ok(c[k]>=-1e-10);for(const r of s.aqua)assert.ok(r.deepGround>=-1e-10&&r.deepGround<=300+1e-10)}return max}
test('P limita fotossíntese e crescimento',()=>{let a=Q.create(),b=Q.create();for(let c of b.cells){c.soilP=0;c.rockP=0;c.sorbedP=0;c.microP=0}run(a,8);run(b,8);assert.ok(a.ledger.carbonIn>b.ledger.carbonIn);assert.ok(a.soilEvents.uptake>b.soilEvents.uptake);results.pLimited={normal:a.soilEvents.uptake,low:b.soilEvents.uptake}});
test('mineralização e imobilização',()=>{let s=Q.create();run(s,12);for(let k of ['mineralized','immobilized','turnover','weathered','rootAccess','sorption'])assert.ok(s.soilEvents[k]>0,k)});
test('3 nascentes com reserva finita',()=>{let s=Q.create();assert.equal(Q.metrics(s).springs,3);s.weather='drought';run(s,360);let m=Q.metrics(s);assert.ok(m.fish>.01&&m.refuges>=1&&m.deepGround<660);results.drought90=m;s.weather='rain';run(s,120);results.recovery30=Q.metrics(s);assert.ok(results.recovery30.deepGround>m.deepGround);assert.ok(results.recovery30.wet>m.wet)});
test('nascente vazia não cria água',()=>{let s=Q.create();s.weather='drought';for(let r of s.aqua){r.ground=r.pond=r.deepGround=0}for(let c of s.cells){c.water=c.surface=0}run(s,8);assert.equal(s.soilEvents.springDischarge,0);assert.equal(s.soilEvents.deepRecharge,0)});
test('contabilidade de P das intervenções terrestres',()=>{let s=Q.create(),i=s.cells.findIndex(c=>!c.channel&&c.sp>=0),before=Q.totals(s).p,l={...s.ledger};for(let action of ['compost','dung','wood','cut'])assert.ok(Q.landEdit(s,i,action));assert.ok(Math.abs(Q.totals(s).p-before-(s.ledger.externalP-l.externalP)+(s.ledger.pOut-l.pOut))<1e-8);run(s,8)});
test('90 dias naturais',()=>{let s=Q.create();results.natural90={max:run(s,360),...Q.metrics(s),events:s.soilEvents};assert.equal(results.natural90.springs,3)});
console.log(JSON.stringify({passed:tests.length,tests,results},null,2));
